-- =============================================================================
-- USCL Season 2 — player registration codes + squad-size update
--
-- 1. Every player gets a unique, human-readable registration code (e.g.
--    "USCL2-7Q3K9M"). Generated by the registration action and shared with the
--    player over email. Stored here so admins can look a player up by their ID.
-- 2. Squad size per franchise updated to 17–22 (still configurable, not
--    hardcoded — nothing-hardcoded rule).
-- =============================================================================

-- 1. Registration code — nullable + unique. The app fills it on insert; older
--    rows (if any) stay NULL, which the UNIQUE index permits.
alter table public.players
  add column if not exists registration_code text;

create unique index if not exists players_registration_code_key
  on public.players (registration_code);

-- 2. Squad size → 17–22 (update the live row and the column defaults).
alter table public.league_settings
  alter column squad_min_per_franchise set default 17,
  alter column squad_max_per_franchise set default 22;

update public.league_settings
  set squad_min_per_franchise = 17,
      squad_max_per_franchise = 22;
